--      audit log are kept.
--   3. Loads 11 types, 17 sizes, 235 SKUs and 7 cases
--      (ຕູ້1..ຕູ້7, B-MM) opened and checked in on 2026-11-27.
-- ============================================================================
begin;

-- 1. Backup (a second run keeps the first backup).
create schema if not exists kpv_backup_20261127;
