do $$ begin
  if (select count(*) from master_sku) <> 235 then raise exception 'RESET_CHECK: SKU count'; end if;
  if (select count(*) from desks) <> 7 then raise exception 'RESET_CHECK: case count'; end if;
  if (select sum(opening_qty) from daily_stock_ledger) <> 6381 then raise exception 'RESET_CHECK: pieces'; end if;
end $$;
insert into audit_log (actor_name, action, target, detail)
